def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]

    # Locate rectangular outlines.
    frames = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if (all(grid[r0][c] == color and grid[r1][c] == color
                for c in range(c0, c1 + 1)) and
            all(grid[r][c0] == color and grid[r][c1] == color
                for r in range(r0, r1 + 1))):
            frames.append((r0, r1, c0, c1, color))

    frame_colors = {f[4] for f in frames}
    for r0, r1, c0, c1, color in frames:
        for c in range(c0, c1 + 1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = out[r][c1] = color

    # Colors outside the frames indicate the checkerboard fills. Match rarer
    # marker colors to smaller frames.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v and v not in frame_colors:
                counts[v] = counts.get(v, 0) + 1
    markers = sorted(counts, key=lambda v: (counts[v], v))
    frames.sort(key=lambda f: (f[1] - f[0] + 1) * (f[3] - f[2] + 1))

    for i, (r0, r1, c0, c1, _) in enumerate(frames):
        if i >= len(markers):
            break
        fill = markers[i]
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if (r - r0 + c - c0) % 2 == 0:
                    out[r][c] = fill

    return out
